    properties (Access = private)
        %v0.2更新：(1)增加1300路电源连接断开，继电器打开关闭，上电功能
        DianyaApp % Description
        PhaseApp
        RegionApp
        CurrentDianya
        CurrentX
        CurrentY
        CurrentZ
        AxisX
        AxisY
        ave
        mydriver % Description
        mymeasure % Description
        No %迭代次数
    end    

    methods (Access = public)

        function updateDianya(app,hang,lie,data)
            app.CurrentDianya(hang,lie)=data;
            app.mydriver.danyuan((hang-1)*36+lie,str2double(data),app.EditFieldHigher.Value,app.EditFieldLower.Value);
        end
    end

    methods (Access = private)

        function updateParameter(app)
            N=sqrt(app.EditFieldNumber.Value);
            pitch=app.EditFieldPitch.Value*1e-3;
            if mod(N,2)==1
                width_qishi=-(N-1)/2*pitch;
            else
                width_qishi=-(N/2*pitch-pitch/2);
            end
            if mod(N,2)==1
                height_qishi=-(N-1)/2*pitch;
            else
                height_qishi=-(N/2*pitch-pitch/2);
            end
            app.AxisX=width_qishi:pitch:width_qishi+pitch*(N-1);
            app.AxisY=height_qishi:pitch:height_qishi+pitch*(N-1);
            app.CurrentDianya=zeros(N,N);
            app.CurrentX=NaN;
            app.CurrentY=NaN;
            app.CurrentZ=NaN;
            app.ave=NaN;            
        end
    end


    % Callbacks that handle component events
    methods (Access = private)

        % Code that executes after component creation
        function startupFcn(app)
            updateParameter(app)

        end

        % Button pushed function: ButtonDianya
        function ButtonDianyaPushed(app, event)
            app.ButtonDianya.Enable='off';
            app.DianyaApp=dianya(app,app.CurrentDianya);
        end

        % Button pushed function: ButtonMeasure
        function ButtonMeasurePushed(app, event)
            app.mymeasure=laser;
            app.mymeasure.chushi();

            saveto_file='D:\BaiduSyncdisk\项目材料\王强\动态承片台\12寸拼接\20241116\initial.dat';
            %saveto_file='D:\BaiduSyncdisk\项目材料\王强\动态承片台\12寸拼接\20241106\41.dat';
            [x,y,z]=read_zygo_center_of_data(saveto_file);
            %%%%%remove plane
            warning off
            [Xfit,Yfit,Zfit]=prepareSurfaceData(x,y,z);
            A=[Xfit,Yfit,ones(length(Xfit),1)];
            a=inv(A'*A)*A'*Zfit;
            z=z-a(3)-a(1)*x-a(2)*(y');
            %%%%%
            app.LabelPV.Text=num2str((max(z(:))-min(z(:)))*1e9);
            app.LabelRMS.Text=num2str(nanstd(z(:))*1e9);
            app.CurrentX=x;
            app.CurrentY=y;
            app.CurrentZ=z;
            [~,~,app.ave]=segmented_mean_2D(x,y,z,app.AxisX,app.AxisY);
            if app.ButtonPhase.Enable=='off'
                updatePhase(app.PhaseApp,app.CurrentX,app.CurrentY,app.CurrentZ);
            else
            end
            if app.ButtonRegion.Enable=='off'
                updateRegion(app.RegionApp,app.AxisX,app.AxisY,app.ave);
            else
            end
        end

        % Button pushed function: ButtonPhase
        function ButtonPhasePushed(app, event)
            app.ButtonPhase.Enable='off';
            app.PhaseApp=phase(app,app.AxisX,app.AxisY,app.CurrentX,app.CurrentY,app.CurrentZ,app.EditFieldAperture.Value*1e-3);
        end

        % Value changed function: EditFieldNumber
        function EditFieldNumberValueChanged(app, event)
            value = app.EditFieldNumber.Value;
            updateParameter(app)
        end

        % Close request function: v02UIFigure
        function v02UIFigureCloseRequest(app, event)
            delete(app.DianyaApp)
            delete(app.PhaseApp)
            delete(app.RegionApp)
            delete(app)            
        end

        % Value changed function: EditFieldTotal
        function EditFieldTotalValueChanged(app, event)
            value = app.EditFieldTotal.Value;            
        end

        % Button pushed function: ButtonTotal
        function ButtonTotalPushed(app, event)
            app.CurrentDianya=ones(size(app.CurrentDianya))*app.EditFieldTotal.Value;
            if app.ButtonDianya.Enable=='off'
                updateVoltage(app.DianyaApp,app.CurrentDianya);
            else
            end
            app.mydriver.zhengti(app.EditFieldTotal.Value,app.EditFieldHigher.Value,app.EditFieldLower.Value);
        end

        % Button pushed function: ButtonInitial
        function ButtonInitialPushed(app, event)
            app.CurrentDianya=zeros(size(app.CurrentDianya));
            if app.ButtonDianya.Enable=='off'
                updateVoltage(app.DianyaApp,app.CurrentDianya);
            else
            end
            app.mydriver.zhengti(0,app.EditFieldHigher.Value,app.EditFieldLower.Value);
        end

        % Button pushed function: ButtonRegion
        function ButtonRegionPushed(app, event)
            app.ButtonRegion.Enable='off';
            app.RegionApp=region(app,app.AxisX,app.AxisY,app.ave);
        end

        % Value changed function: EditFieldPitch
        function EditFieldPitchValueChanged(app, event)
            value = app.EditFieldPitch.Value;
            updateParameter(app)
        end

        % Button pushed function: ButtonCalculate
        function ButtonCalculatePushed(app, event)
            zhongzhi=nanmean(app.ave);
            app.CurrentDianya=(zhongzhi-app.ave)*1e9/20;
            if app.ButtonDianya.Enable=='off'
                updateVoltage(app.DianyaApp,app.CurrentDianya);
            else
            end
        end

        % Value changed function: EditFieldAperture
        function EditFieldApertureValueChanged(app, event)
            value = app.EditFieldAperture.Value;

        end

        % Button pushed function: ButtonConnect
        function ButtonConnectPushed(app, event)
            app.mydriver=driver1300v1;
            app.mydriver.duiying();
            app.mydriver.lianjie();            
        end

        % Button pushed function: ButtonDisconnect
        function ButtonDisconnectPushed(app, event)
            app.mydriver.duankai();
        end

        % Button pushed function: ButtonOpenRelay
        function ButtonOpenRelayPushed(app, event)
            app.mydriver.relaystate(1);
        end

        % Button pushed function: ButtonCloseRelay
        function ButtonCloseRelayPushed(app, event)
            app.mydriver.relaystate(0);
        end
    end

